import LiveStrategySettings, {defaultLiveStrategyConfig, type LiveStrategyConfig} from './components/LiveStrategySettings';
import { lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Activity, Archive, ArrowDownLeft, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, BookOpen, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Clock3, Copy, Download, ExternalLink, Eye, LayoutDashboard, Link2, Lock, Unlock, LoaderCircle, MoreHorizontal, Pause, Play, Plus, Power, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Square, Target, Trash2, TrendingUp, Users, Wallet, Wifi, WifiOff, X, Zap } from 'lucide-react';
import CandleChart, { type Candle } from './components/CandleChart';
const BacktestPanel=lazy(()=>import('./components/BacktestPanel'));
const BacktestHistory=lazy(()=>import('./components/BacktestHistory'));
const readPage=()=>{const value=window.location.hash.slice(1).split('?')[0];return ['dashboard','accounts','analytics','strategy','backtest','backtest-history','bridge'].includes(value)?value as Page:'dashboard';};

type Mode = 'paper' | 'browser';
type Page = 'dashboard' | 'accounts' | 'analytics' | 'strategy' | 'backtest' | 'backtest-history' | 'bridge';
type Stamp = string | number;
type Phase = '1/2' | '2/2' | 'live';
type PhaseBook = { phase: Phase; capital_metrics?: CapitalMetrics; balance?: number | null; history_realized_pnl?: number; history_trade_count?: number; daily_realized_pnl?: number; daily_entry_used?: boolean; started_at?: Stamp; ended_at?: Stamp; settlement_pending?: boolean };
const phases: Phase[] = ['1/2', '2/2', 'live'];
type CapitalMetric = { phase?: Phase; text: string; current: number | null; limit: number | null; percent: number | null; observed_at: number; category: string; update_pending?: boolean };
type CapitalMetrics = Partial<Record<'daily_loss' | 'drawdown' | 'goal', CapitalMetric | null>>;
type Account = { phase?: Phase; phase_pending?: { phase: Phase; reason: string }; phase_books?: Partial<Record<Phase, PhaseBook>>; phase_realized_pnl?: number | null; available?: boolean; archived?: boolean; archived_at?: Stamp; archive_source?: string; archive_kind?: 'manual' | 'terminal'; retired_failed?: boolean; capital_metrics?: CapitalMetrics; execution_excluded?: boolean; execution_exclusion_reason?: string; id: string; name: string; balance: number | null; initial_balance: number | null; profit_target: number | null; max_loss: number | null; realized_pnl: number | null; daily_realized_pnl?: number; daily_trade_count?: number; daily_entry_used?: boolean; unrealized_pnl: number | null; equity: number | null; status: string; enabled: boolean; mode: Mode; ready?: boolean; connected?: boolean; data_stale?: boolean; observed_at?: Stamp; lock_reason?: string | null; auto_discovered?: boolean; category?: string; identity?: string; session_id?: string; execution_mode?: 'readonly' | 'execute'; executable?: boolean; baseline_source?: string; strategy_locked?: boolean; strategy_lock_reason?: string | null; strategy_lock_source?: string | null; strategy_locked_at?: Stamp | null; strategy_unlock_at?: Stamp | null };
type Position = { id: string; account_id: string; account_name: string; symbol: string; side: 'buy' | 'sell'; quantity: number; entry_price: number; mark_price: number | null; unrealized_pnl: number | null; mode?: Mode; data_stale?: boolean; take_profit: number | null; stop_loss: number | null; opened_at: Stamp; source: string; status: string };
type Trade = { phase?: Phase; id: string; account_id: string; account_name: string; symbol: string; side: string; quantity: number; entry_price: number; exit_price: number; pnl: number; reason: string; opened_at: Stamp; closed_at: Stamp; mode?: Mode };
type StrategyConfig = LiveStrategyConfig & { strategy_id: string; account_ids: string[]; batch_size: number; order_delay_min: number; order_delay_max: number; batch_delay_min: number; batch_delay_max: number; size_percent: number; take_profit: number | null; stop_loss: number; side: 'random' | 'buy' | 'sell'; symbol: string; skip_stop_loss_on_low_drawdown: boolean; drawdown_stop_loss_threshold: number };
type StrategyForm = Omit<StrategyConfig, 'account_ids'>;
const defaultStrategyForm: StrategyForm = { ...defaultLiveStrategyConfig, strategy_id: 'random_entry', batch_size: 2, order_delay_min: 2, order_delay_max: 8, batch_delay_min: 15, batch_delay_max: 45, size_percent: 25, take_profit: null, stop_loss: 130, side: 'random', symbol: 'NQ-PERP', skip_stop_loss_on_low_drawdown: false, drawdown_stop_loss_threshold: 200 };
type BridgeJob = { id: string; account_id: string; type: 'open' | 'close'; status: string; created_at: Stamp; error?: string | null };
type ObservedAccount = { phase?: Phase; phase_stale?: boolean; capital_metrics?: CapitalMetrics; execution_excluded?: boolean; key: string; name: string; category: string; identity?: string; equity: number | null; balance: number | null; unrealized_pnl: number | null; current: boolean; observed_at: number | null; stale: boolean; source: 'vest-page'; read_error?: string | null; ambiguous?: boolean };
type AccountObservation = { connected: boolean; last_seen: number | null; error: string | null; accounts: ObservedAccount[] };
type State = { strategies?: {id: string; name: string; description: string}[]; preferences?: {auto_archive_failed: boolean; strategy_config?: StrategyForm}; trading_day?: {start: number; end: number; label: string; timezone: string; cutoff: string}; mode: Mode; accounts: Account[]; positions: Position[]; history: Trade[]; market: { symbol: string; price: number | null; change: number | null; change_pct: number | null; high: number | null; low: number | null; volume: number | null; source: string; observed_since?: Stamp | null; updated_at?: Stamp | null }; candles: Candle[]; strategy: { status: string; batch_number: number; batch_account_ids: string[]; completed_accounts: string[] | number; remaining_accounts: string[] | number; next_action_at: Stamp | null; config: Partial<StrategyConfig> }; logs: { id: string; time: Stamp; level: string; message: string }[]; bridge: { connected_accounts: string[]; ready_accounts?: string[]; pending_jobs: number; jobs?: BridgeJob[] }; connection: Record<string, unknown> };
type Toast = { id: number; message: string; error: boolean };

const money = (n: number | null | undefined, decimals = 2) => n == null ? '—' : Number(n).toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
const signed = (n: number | null | undefined) => n == null ? '—' : `${n >= 0 ? '+' : '−'}${money(Math.abs(n))}`;
const dateValue = (value: Stamp | null | undefined) => typeof value === 'number' ? value * (value < 1e12 ? 1000 : 1) : value ? new Date(value).getTime() : 0;
const dateText = (value: Stamp, short = false) => new Date(dateValue(value)).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', ...(short ? {} : { year: 'numeric' }) });
const count = (value: string[] | number) => Array.isArray(value) ? value.length : Number(value || 0);
const statusNames: Record<string, string> = { active: '交易中', passed: '已达目标', locked: '触及风控', idle: '尚未启动', running: '执行中', waiting: '批间等待', stopped: '已停止', completed: '本轮完成', paused: '已暂停', open: '持仓中', pending: '等待确认', closing: '平仓确认中', pending_close: '平仓确认中', pending_open: '开仓确认中', unknown: '结果待核验' };
const reasonNames: Record<string, string> = { external: '网页平仓', take_profit: '止盈', stop_loss: '止损', manual: '手动平仓', target: '达到目标', risk_limit: '账户风控', max_loss: '账户风控', demo: '模拟结算' };
const pageInfo: Record<Page, { title: string; subtitle: string }> = { dashboard: { title: '交易工作台', subtitle: '每个账户的动态，尽在掌握。' }, accounts: { title: '账户管理', subtitle: '统一管理账户，独立执行每一笔交易。' }, analytics: { title: '盈亏分析', subtitle: '从交易记录中，看见账户的真实表现。' }, strategy: { title: '自动策略', subtitle: '设定规则，让批次有序执行。' }, 'backtest-history': { title: '回测历史', subtitle: '按名称与条件查找记录，查看已保存的回测统计。' }, backtest: { title: '策略回测', subtitle: '用本地历史数据检验策略、考核与分润表现。' }, bridge: { title: '浏览器连接', subtitle: '连接已登录的 Vest 页面，使用可观察的网页操作。' } };

async function request<T>(path: string, body?: unknown, method?: string): Promise<T> {
  const response = await fetch(path, { method: method || (body === undefined ? 'GET' : 'POST'), headers: body === undefined ? {} : { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(10000) });
  const text = await response.text();
  let result: any;
  try { result = text ? JSON.parse(text) : {}; } catch { throw new Error('交易服务返回了无法识别的响应，请检查本地服务。'); }
  if (!response.ok) throw new Error(result.error || `请求失败 (${response.status})`);
  return result;
}

function Field({ label, suffix, children, hint }: { label: string; suffix?: string; children: ReactNode; hint?: string }) {
  return <label className="field"><span className="field-label">{label}{suffix && <span>{suffix}</span>}</span>{children}{hint && <small>{hint}</small>}</label>;
}

function EquityChart({ trades, initial = 0, compact = false }: { trades: Trade[]; initial?: number; compact?: boolean }) {
  const points = useMemo(() => {
    let value = initial;
    return [value, ...[...trades].sort((a, b) => dateValue(a.closed_at) - dateValue(b.closed_at)).map(trade => (value += trade.pnl))];
  }, [trades, initial]);
  const width = 800, height = compact ? 140 : 240, pad = 20;
  const min = Math.min(...points), max = Math.max(...points), range = max - min || 1;
  const coords = points.map((point, index) => `${pad + index / Math.max(1, points.length - 1) * (width - pad * 2)},${height - pad - (point - min) / range * (height - pad * 2)}`).join(' ');
  const line = `M ${coords.replaceAll(' ', ' L ')}`;
  const id = compact ? 'equity-compact' : 'equity-full';
  return <div className={`equity-chart ${compact ? 'compact' : ''}`}><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="已实现累计盈亏曲线" preserveAspectRatio="none"><defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#e7b74a" stopOpacity=".22" /><stop offset="100%" stopColor="#e7b74a" stopOpacity="0" /></linearGradient></defs>{[0, 1, 2, 3].map(i => <line key={i} x1="0" x2={width} y1={pad + i * (height - 2 * pad) / 3} y2={pad + i * (height - 2 * pad) / 3} stroke="#242831" strokeDasharray="4 5" />)}<path d={`${line} L ${width - pad},${height} L ${pad},${height} Z`} fill={`url(#${id})`} /><path d={line} fill="none" stroke="#e7b74a" strokeWidth="2.5" vectorEffect="non-scaling-stroke" /></svg>{!compact && <div className="chart-axis"><span>{trades.length ? dateText([...trades].sort((a, b) => dateValue(a.closed_at) - dateValue(b.closed_at))[0].closed_at, true) : '暂无记录'}</span><span>累计已实现盈亏 · USDC</span><span>{trades.length ? dateText([...trades].sort((a, b) => dateValue(b.closed_at) - dateValue(a.closed_at))[0].closed_at, true) : '—'}</span></div>}</div>;
}

export default function App() {
  const [data, setData] = useState<State | null>(null);
  const [page, setPage] = useState<Page>(readPage);
  useEffect(()=>{const changed=()=>setPage(readPage());window.addEventListener('hashchange',changed);return()=>window.removeEventListener('hashchange',changed);},[]);
  useEffect(()=>{if(readPage()!==page)window.location.hash=page;},[page]);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState('');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [tableTab, setTableTab] = useState<'accounts' | 'positions' | 'history'>('accounts');
  const [period, setPeriod] = useState(1);
  const [side, setSide] = useState<'buy' | 'sell'>('buy');
  const [quantity, setQuantity] = useState(1);
  const takeProfit = null;
  const [stopLoss, setStopLoss] = useState(130);
  const [showAdd, setShowAdd] = useState(false);
  const [phaseDetailId, setPhaseDetailId] = useState<string | null>(null);
  const [accountDraft, setAccountDraft] = useState({ name: '', initial_balance: 10000, profit_target: 800, max_loss: 500 });
  const [search, setSearch] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [historyAccount, setHistoryAccount] = useState('all');
  const [historyDays, setHistoryDays] = useState(30);
  const [historyResult, setHistoryResult] = useState('all');
  const [now, setNow] = useState(Date.now());
  const [bridgeConfig, setBridgeConfig] = useState<{ token: string; endpoint: string } | null>(null);
  const [observation, setObservation] = useState<AccountObservation | null>(null);
  const [observationError, setObservationError] = useState('');
  const [confirmAction, setConfirmAction] = useState<{ title: string; description: string; run: () => void } | null>(null);
  const [strategyForm, setStrategyForm] = useState<StrategyForm>(defaultStrategyForm);
  const [strategyLoaded, setStrategyLoaded] = useState(false);
  const [strategySave, setStrategySave] = useState({status:'loading', error:''});
  const strategyFormRef = useRef(defaultStrategyForm);
  const strategyInitialized = useRef(false);
  const strategySaveVersion = useRef(0);
  const strategySaves = useRef<Promise<void>>(Promise.resolve());
  const initialSelection = useRef<Mode | null>(null);
  const activeFetch = useRef(false);
  const activeObservationFetch = useRef(false);

  const toast = useCallback((message: string, isError = false) => {
    const id = Date.now() + Math.random();
    setToasts(current => [...current.slice(-2), { id, message, error: isError }]);
    window.setTimeout(() => setToasts(current => current.filter(item => item.id !== id)), 5000);
  }, []);
  const saveStrategyForm = (form: StrategyForm) => {
    const version = ++strategySaveVersion.current;
    setStrategySave({status:'saving',error:''});
    // Serialize writes so a slow older save cannot overwrite the latest edit.
    strategySaves.current = strategySaves.current.catch(() => {}).then(async () => {
      try {
        await request<StrategyForm>('/api/strategy/config',form);
        if (version === strategySaveVersion.current) setStrategySave({status:'saved',error:''});
      } catch (caught) {
        if (version === strategySaveVersion.current) setStrategySave({status:'error',error:caught instanceof Error ? caught.message : '无法保存参数'});
      }
    });
  };
  const updateStrategyForm = (patch: Partial<StrategyForm>) => {
    const next = {...strategyFormRef.current,...patch};
    strategyFormRef.current = next;
    setStrategyForm(next);
    saveStrategyForm(next);
  };
  useEffect(() => {
    if (!data || strategyInitialized.current) return;
    const saved = data.preferences?.strategy_config;
    if (!saved || saved.live_default_locked === undefined || saved.live_stop_loss === undefined) {
      setStrategySave({status:'upgrade',error:''});
      return;
    }
    const restored = {...defaultStrategyForm};
    for (const key of Object.keys(defaultStrategyForm) as (keyof StrategyForm)[]) {
      if (saved[key] !== undefined) Object.assign(restored,{[key]:saved[key]});
    }
    restored.take_profit = null;
    strategyInitialized.current = true;
    strategyFormRef.current = restored;
    setStrategyForm(restored);
    setStrategyLoaded(true);
    setStrategySave({status:'saved',error:''});
  }, [data]);
  const refresh = useCallback(async () => {
    if (activeFetch.current) return;
    activeFetch.current = true;
    try { const state = await request<State>('/api/state'); setData(state); setError(''); } catch (caught) { setError(caught instanceof Error ? caught.message : '无法连接本地交易服务'); } finally { activeFetch.current = false; }
  }, []);
  const refreshObservation = useCallback(async () => {
    if (activeObservationFetch.current) return;
    activeObservationFetch.current = true;
    try {
      const result = await request<AccountObservation>('/api/account-observation');
      if (!result || !Array.isArray(result.accounts)) throw new Error('账户读取服务返回了无法识别的数据');
      setObservation(result);
      setObservationError('');
    } catch (caught) {
      // Observation failure must not interrupt the paper engine or trading controls.
      setObservationError(caught instanceof Error ? caught.message : '暂时无法同步 Vest 页面读取结果');
    } finally { activeObservationFetch.current = false; }
  }, []);
  useEffect(() => { void refresh(); const timer = window.setInterval(refresh, 1000); return () => clearInterval(timer); }, [refresh]);
  useEffect(() => {
    if (data?.mode !== 'browser' && page !== 'bridge') return;
    void refreshObservation();
    const timer = window.setInterval(refreshObservation, 2000);
    return () => clearInterval(timer);
  }, [data?.mode, page, refreshObservation]);
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, []);
  useEffect(() => {
    const handler = (event: KeyboardEvent) => { if (event.key === 'Escape') { setShowAdd(false); setConfirmAction(null); setPhaseDetailId(null); } };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, []);
  useEffect(() => { document.body.style.overflow = showAdd || confirmAction || phaseDetailId ? 'hidden' : ''; return () => { document.body.style.overflow = ''; }; }, [showAdd, confirmAction, phaseDetailId]);
  useEffect(() => {
    if (!data) return;
    const available = data.accounts.filter(a => a.mode === data.mode && (a.mode === 'paper' || a.auto_discovered === true) && !a.execution_excluded && a.enabled && a.status === 'active');
    if (initialSelection.current !== data.mode) { setSelected(available.map(a => a.id)); setHistoryAccount('all'); initialSelection.current = data.mode; }
    else setSelected(current => current.filter(id => data.accounts.some(a => a.id === id && a.mode === data.mode)));
  }, [data?.mode, data?.accounts.length]);

  const perform = async (path: string, body: unknown, success: string, method?: string) => {
    if (busy) return false;
    setBusy(path);
    try { const result = await request<{ok?: boolean; results?: {error?: string}[]}>(path, body, method); if (result.ok === false) throw new Error(result.results?.filter(item => item.error).map(item => item.error).join('；') || '部分操作未成功，请核对当前持仓'); toast(success); await refresh(); return true; } catch (caught) { toast(caught instanceof Error ? caught.message : '操作失败', true); return false; } finally { setBusy(''); }
  };

  const mode = data?.mode || 'paper';
  const observedAccounts = useMemo(() => {
    const unique = new Map<string, ObservedAccount>();
    for (const account of observation?.accounts || []) {
      if (account.source !== 'vest-page' || !account.key) continue;
      const previous = unique.get(account.name);
      if (!previous || dateValue(account.observed_at) >= dateValue(previous.observed_at)) unique.set(account.name, account);
    }
    return [...unique.values()];
  }, [observation?.accounts]);
  const observationIssue = observationError || observation?.error || '';
  const observedIsFresh = (account: ObservedAccount) => observation?.connected === true && !observationIssue && !account.stale;
  const activeObservedAccounts = observedAccounts.filter(row => !(data?.accounts || []).some(account => account.mode === 'browser' && account.archived && account.name === row.name));
  const freshObservedAccounts = activeObservedAccounts.filter(observedIsFresh);
  const observedTotal = (field: 'equity' | 'balance' | 'unrealized_pnl') => {
    const readings = activeObservedAccounts.map(row => {
      const current = data?.accounts.find(account => account.mode === 'browser' && account.name === row.name);
      return current?.phase && (row.phase !== current.phase || row.phase_stale) ? {
        ...row, phase: current.phase, [field]: current[field], observed_at: dateValue(current.observed_at) / 1000 || null, stale: true,
      } : row;
    });
    const known = readings.filter(account => !!account.observed_at && typeof account[field] === 'number' && Number.isFinite(account[field]));
    return { value: known.length ? known.reduce((total, account) => total + (account[field] ?? 0), 0) : null, count: known.length, pending: known.filter(account => !observedIsFresh(account)).length };
  };
  const observedEquity = observedTotal('equity');
  const observedBalance = observedTotal('balance');
  const observedUnrealized = observedTotal('unrealized_pnl');
  const discoveredBrowserAccounts = useMemo(() => (data?.accounts || []).filter(account => account.mode === 'browser' && account.auto_discovered === true), [data?.accounts]);
  const accounts = useMemo(() => mode === 'browser' ? discoveredBrowserAccounts.filter(account => !account.archived) : (data?.accounts || []).filter(account => account.mode === 'paper'), [data?.accounts, discoveredBrowserAccounts, mode]);
  const archivedAccountCount = discoveredBrowserAccounts.filter(account => account.archived).length;
  const browserRows = useMemo(() => {
    const remaining = new Set(discoveredBrowserAccounts.map(account => account.id));
    const rows: { key: string; account?: Account; observed?: ObservedAccount }[] = observedAccounts.map(observed => {
      const matches = discoveredBrowserAccounts.filter(account => account.name === observed.name);
      const account = matches.length === 1 ? matches[0] : undefined;
      if (account) remaining.delete(account.id);
      return { key: account ? `account:${account.id}` : observed.key, account, observed };
    });
    for (const account of discoveredBrowserAccounts) if (remaining.has(account.id)) rows.push({ key: `account:${account.id}`, account });
    return rows.filter(row => showArchived || !row.account?.archived);
  }, [discoveredBrowserAccounts, observedAccounts, showArchived]);
  const executionAccounts = discoveredBrowserAccounts.filter(account => account.executable === true);
  const accountIds = useMemo(() => new Set((data?.accounts || []).filter(account => account.mode === mode).map(account => account.id)), [data?.accounts, mode]);
  const positions = useMemo(() => (data?.positions || []).filter(p => p.mode ? p.mode === mode : accountIds.has(p.account_id)), [data?.positions, accountIds, mode]);
  const history = useMemo(() => (data?.history || []).filter(t => t.mode ? t.mode === mode : accountIds.has(t.account_id)), [data?.history, accountIds, mode]);
  const unresolvedJobs = (data?.bridge.jobs || []).filter(job => ['queued', 'delivered', 'unknown'].includes(job.status));
  const accountJob = (id: string) => unresolvedJobs.filter(job => job.account_id === id).sort((a, b) => (a.status === 'unknown' ? -1 : b.status === 'unknown' ? 1 : dateValue(b.created_at) - dateValue(a.created_at)))[0];
  const phaseDetail = data?.accounts.find(a => a.id === phaseDetailId);
  const eligible = accounts.filter(a => !a.phase_pending && !a.execution_excluded && a.enabled && a.status === 'active' && !a.daily_entry_used && !positions.some(p => p.account_id === a.id) && !accountJob(a.id) && (mode === 'paper' || a.executable === true));
  const selectedEligible = selected.filter(id => eligible.some(a => a.id === id));
  const strategyEligible = eligible.filter(account => !account.strategy_locked);
  const selectedStrategy = selected.filter(id => strategyEligible.some(account => account.id === id));
  const equity = accounts.reduce((sum, a) => sum + (a.equity ?? 0), 0);
  const staleTotals = accounts.some(a => a.equity == null || a.unrealized_pnl == null);
  const realized = accounts.reduce((sum, a) => sum + (a.realized_pnl ?? 0), 0);
  const unrealized = accounts.reduce((sum, a) => sum + (a.unrealized_pnl ?? 0), 0);
  const todayTrades = history.filter(t => data?.trading_day && dateValue(t.closed_at) >= data.trading_day.start * 1000 && dateValue(t.closed_at) < data.trading_day.end * 1000 && dateValue(t.closed_at) <= now);
  const todayPnl = todayTrades.reduce((sum, t) => sum + t.pnl, 0);
  const strategyRunning = ['running', 'waiting'].includes(data?.strategy.status || '');
  const strategyPaused = data?.strategy.status === 'paused';
  const strategyNeedsVerification = strategyPaused && unresolvedJobs.some(job => ['unknown','delivered'].includes(job.status));
  const strategyUnresolved = strategyPaused && (unresolvedJobs.length > 0 || positions.length > 0);
  const filteredHistory = history.filter(t => (historyAccount === 'all' || t.account_id === historyAccount) && (!historyDays || dateValue(t.closed_at) >= now - historyDays * 86400000) && (historyResult === 'all' || (historyResult === 'profit' ? t.pnl > 0 : t.pnl < 0)));
  const winners = filteredHistory.filter(t => t.pnl > 0).length;
  const winRate = filteredHistory.length ? winners / filteredHistory.length * 100 : 0;
  const filteredPnl = filteredHistory.reduce((sum, t) => sum + t.pnl, 0);
  const profitSum = filteredHistory.filter(t => t.pnl > 0).reduce((sum, t) => sum + t.pnl, 0);
  const lossSum = Math.abs(filteredHistory.filter(t => t.pnl < 0).reduce((sum, t) => sum + t.pnl, 0));

  const toggleSelection = (id: string) => setSelected(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);
  const selectAll = () => setSelected(selectedEligible.length === eligible.length ? [] : eligible.map(a => a.id));
  const selectStrategyAll = () => setSelected(selectedStrategy.length === strategyEligible.length ? [] : strategyEligible.map(account => account.id));
  const switchMode = (next: Mode) => {
    if (next === mode) return;
    setBridgeConfig(null);
    void perform('/api/settings', { mode: next }, '工作台已切换；真实执行权限由插件模式控制');
  };
  const submitOrder = (event: FormEvent) => {
    event.preventDefault();
    if (!selectedEligible.length) return toast('请先选择至少一个可交易的账户', true);
    const run = () => void perform('/api/orders', { account_ids: selectedEligible, side, quantity: mode === 'browser' ? quantity * 2 : quantity, take_profit: takeProfit, stop_loss: stopLoss, symbol: 'NQ-PERP', idempotency_key: crypto.randomUUID() }, mode === 'paper' ? `已向 ${selectedEligible.length} 个模拟账户提交订单` : '订单已提交浏览器，等待页面确认');
    run();
  };
  const startStrategy = (event: FormEvent) => {
    event.preventDefault();
    if (selectedStrategy.length < strategyForm.batch_size) return toast('未锁定的策略账户不足一个完整批次', true);
    if (strategyForm.order_delay_max < strategyForm.order_delay_min || strategyForm.batch_delay_max < strategyForm.batch_delay_min) return toast('随机延迟的上限不能小于下限', true);
    const run = async () => {
      await strategySaves.current;
      await perform('/api/strategy/start', { ...strategyFormRef.current, account_ids: selectedStrategy }, '随机批次策略已启动');
    };
    run();
  };
  const exportHistory = () => {
    const header = ['记录ID', '账户', '合约', '方向', '数量', '开仓价', mode === 'browser' ? '平仓观察价' : '平仓价', mode === 'browser' ? '余额变化USDC' : '盈亏USDC', '平仓原因', '开仓时间', '平仓时间', '统计口径', '阶段'];
    const rows = filteredHistory.map(t => [t.id, t.account_name, t.symbol, t.side, t.quantity, t.entry_price, t.exit_price, t.pnl, t.reason, dateText(t.opened_at), dateText(t.closed_at), mode === 'browser' ? '开平仓间现金余额差，含费用及其他资金变动，非精确成交损益；平仓价为网页观察价' : '本地模拟成交损益', t.phase || '未识别']);
    const cell = (value: unknown) => { const valueString = String(value); return `"${(typeof value === 'string' && /^[=+@\-\t\r]/.test(valueString) ? "'" : '') + valueString.replaceAll('"', '""')}"`; };
    const blob = new Blob(['\uFEFF' + [header, ...rows].map(row => row.map(cell).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `vest-${mode}-history-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); toast(`已导出 ${filteredHistory.length} 笔交易`);
  };
  const copy = async (value: string) => { try { await navigator.clipboard.writeText(value); toast('已复制到剪贴板'); } catch { toast('无法访问剪贴板，请手动选择并复制', true); } };
  const copyPairingCode = async () => {
    if (busy) return;
    setBusy('pairing');
    try {
      const config = bridgeConfig || await request<{ token: string; endpoint: string }>('/api/bridge/config');
      setBridgeConfig(config);
      await navigator.clipboard.writeText(config.token);
      toast('配对码已复制，请粘贴到扩展后直接读取 Vest 账户');
    } catch (caught) { toast(caught instanceof Error ? caught.message : '无法复制配对码，请在连接指南中手动复制', true); }
    finally { setBusy(''); }
  };

  const dailyPnlTitle = `按本工具已记录的平仓交易历史汇总；美东 17:00 日切，自动处理夏令时。${data?.trading_day ? `当前区间（北京时间）：${dateText(data.trading_day.start)} 至 ${dateText(data.trading_day.end)}。` : ''}`;
  const DailyRealizedCell = (account?: Account) => <td className={`numeric daily-realized-pnl ${account?.daily_realized_pnl == null ? 'dim' : account.daily_realized_pnl >= 0 ? 'positive' : 'negative'}`} title={`${dailyPnlTitle} ${account?.phase ? `仅当前 ${account.phase} 阶段。` : ''}已记录 ${account?.daily_trade_count ?? 0} 笔。`}>{signed(account?.daily_realized_pnl)}</td>;

  const CapitalMetricCell = (key: keyof CapitalMetrics, account?: Account, observed?: ObservedAccount) => {
    const readings = [account?.capital_metrics?.[key], observed?.capital_metrics?.[key]].filter((item): item is CapitalMetric => !!item && (!account?.phase || item.phase === account.phase));
    const metric = readings.sort((a,b) => b.observed_at-a.observed_at || Number(!!b.update_pending)-Number(!!a.update_pending))[0];
    const connected = account ? account.connected === true : observation?.connected === true;
    const pending = !!metric && (metric.update_pending || !connected || now-metric.observed_at*1000>30000 || metric.category !== (account?.category || observed?.category));
    return <td key={key} className="numeric capital-metric-cell" title={metric ? `Vest 页面读数：${metric.text}；观察时间 ${dateText(metric.observed_at)}${pending ? '；保留上次信息，等待更新' : ''}` : '等待插件读取 Vest 页面左上角指标；未显示的指标不推算'}><strong>{metric ? metric.percent != null ? `${money(metric.percent,2)}%` : `${money(metric.current)} / ${money(metric.limit)}` : '—'}</strong>{pending && <small className="capital-metric-pending">待更新</small>}{metric?.percent != null && <small>页面显示比例</small>}</td>;
  };

  const StrategyLockControl = (account: Account, compact = false) => account.execution_excluded || account.retired_failed || account.archived ? <div className="strategy-lock-control"><span className="status-pill strategy-locked" title={account.retired_failed ? account.lock_reason || undefined : account.execution_exclusion_reason}><Lock size={11} />{account.retired_failed ? (account.category === 'closed' ? '已关闭停用' : '评估失败停用') : account.archived ? '已手动归档' : '永久排除'}</span>{!compact && <small className="strategy-lock-reason">{account.retired_failed || account.archived ? '保留记录 · 不参与执行' : '仅展示信息 · 不自动解锁'}</small>}</div> : <div className={`strategy-lock-control ${compact ? 'compact' : ''}`}>
    {!compact && <span className={`status-pill ${account.strategy_locked ? 'strategy-locked' : 'muted'}`} title={account.strategy_lock_reason || '可参与自动策略'}>{account.strategy_locked ? <Lock size={11} /> : <Unlock size={11} />}{account.strategy_locked ? ({ take_profit: '止盈锁定', stop_loss: '止损锁定', evaluation_passed: '通过评估锁定', live_default: 'Live 默认锁定', external_close: '交易结束锁定', daily_completed: '当日交易结束锁定', target_reached: '账户目标锁定', manual: '手动锁定' } as Record<string, string>)[account.strategy_lock_source || ''] || '策略已锁定' : '未锁定'}</span>}
    <button type="button" className="button ghost small" aria-label={`${account.strategy_locked ? '解除策略锁定' : '锁定策略'} ${account.name}`} disabled={!!busy || (!!account.strategy_locked && (account.status === 'passed' || account.category === 'passed'))} title={account.strategy_locked ? account.status === 'passed' ? '已通过评估的账户不再进入自动策略' : account.strategy_lock_reason || '解除后可在下一轮策略重新选择' : '排除后续自动开仓，已有持仓继续保护'} onClick={event => { event.preventDefault(); event.stopPropagation(); void perform(`/api/accounts/${account.id}/strategy-lock`, { locked: !account.strategy_locked }, account.strategy_locked ? '已解除策略锁定；不会自动加入正在运行的批次' : '账户已锁定，不再参与后续自动开仓'); }}>{account.strategy_locked ? <Unlock size={13} /> : <Lock size={13} />}{compact ? account.strategy_locked ? '已锁定' : '锁定' : account.strategy_locked ? '解除' : '锁定'}</button>
    {!compact && account.strategy_locked && <small className="strategy-lock-reason">{account.strategy_lock_reason}{account.strategy_unlock_at && <><br />{dateText(account.strategy_unlock_at, true)} 自动解锁</>}</small>}
  </div>;

  const ArchiveAction = (account: Account) => {
    if (account.execution_excluded || account.archived) return null;
    const jobs = unresolvedJobs.filter(job => job.account_id === account.id);
    const hasPosition = positions.some(position => position.account_id === account.id);
    const uncertain = jobs.some(job => job.status !== 'queued' || job.type !== 'open');
    const confirmFailure = !account.retired_failed && uncertain && (['failed', 'closed'].includes(account.category || '') ||
      (account.status === 'locked' && (account.available === false || account.category === 'unknown')));
    const blocked = hasPosition || (uncertain && !confirmFailure);
    return <button className="button small ghost" aria-label={`归档 ${account.name}`} disabled={!!busy || blocked || (confirmFailure && strategyRunning)} title={hasPosition ? '请先结束持仓后再归档' : blocked ? '仍有未确认交易，请先核对' : confirmFailure && strategyRunning ? '请先停止策略，再明确确认评估失败' : '移出默认列表和执行账户池，保留余额及历史'} onClick={() => setConfirmAction({
      title: confirmFailure ? `确认 ${account.name} 评估失败并归档？` : `归档 ${account.name}？`,
      description: confirmFailure ? '请确认该账户确实已评估失败。此操作会结束该号旧异常并永久停用，不会推测成交或盈亏。' : '归档后移出默认列表和执行账户池，取消尚未派发的开仓，保留余额、平台状态和历史记录。可勾选「显示已归档」查看，其他账户继续原策略。',
      run: () => void perform(`/api/accounts/${account.id}/archive`, { acknowledge: true, ...(confirmFailure ? { terminal_status: 'failed' } : {}) }, '账户已手动归档，原始记录保留'),
    })}><Archive size={13} />{confirmFailure ? '确认失败并归档' : '归档'}</button>;
  };

  const BrowserAccountTable = ({ management = false }: { management?: boolean } = {}) => <>
    <div className="observation-source"><span className={`status-pill ${executionAccounts.length ? 'positive' : 'muted'}`}><i />{executionAccounts.length ? `${executionAccounts.length} 个账户可执行` : '只读模式'}</span><span>模式仅在浏览器插件中切换 · 账户从 Vest 自动发现</span>{!!observation?.last_seen && <span className="observation-last-seen">最近同步 {dateText(observation.last_seen, true)} UTC+8</span>}</div>
    <div className="account-archive-tools"><label><input type="checkbox" aria-label="自动归档失败账户" checked={data?.preferences?.auto_archive_failed !== false} disabled={!!busy} onChange={event => void perform('/api/settings', { auto_archive_failed: event.target.checked }, event.target.checked ? '已开启失败账户自动归档' : '已关闭自动归档；失败账户仍自动停用并结束任务')} />自动归档失败账户</label><label><input type="checkbox" aria-label="显示已归档账户" checked={showArchived} onChange={event => setShowArchived(event.target.checked)} />显示已归档 <span>({archivedAccountCount})</span></label><small>手动归档可用于非主账户；自动归档仅处理已确认失败或关闭的账号</small></div>
    {observationIssue && <div className="observation-warning"><WifiOff size={13} /><span>页面数据同步状态：{observationIssue}。尚未读取的金额显示「—」，过期读数保留并标记「待更新」。</span></div>}
    {browserRows.length ? <div className="table-scroll"><table className="observed-account-table browser-account-table"><thead><tr><th className="check-cell"><input aria-label="选择全部可交易账户" type="checkbox" checked={mode === 'browser' && eligible.length > 0 && selectedEligible.length === eligible.length} disabled={mode !== 'browser' || !eligible.length || strategyRunning} onChange={selectAll} /></th><th>Vest 账户 / 类型</th><th>阶段</th><th>插件模式</th><th className="numeric">现金余额 <span>USDC</span></th><th className="numeric">账户净值 <span>USDC</span></th><th className="numeric">浮动盈亏 <span>USDC</span></th><th className="numeric daily-pnl-heading" title={dailyPnlTitle}>当日已实现盈亏 <span>USDC</span><small>美东 17:00 日切</small></th><th className="numeric" title="仅汇总当前阶段已记录的平仓历史">阶段已实现盈亏 <span>USDC</span></th><th className="numeric">最大日亏损 <span>USDC</span><small>已用 / 上限</small></th><th className="numeric">最大回撤 <span>USDC</span><small>已用 / 上限</small></th><th className="numeric">阶段目标 <span>USDC</span><small>已完成 / 目标</small></th><th>账户状态</th><th>策略锁定</th><th>{management ? '处理' : '持仓 / 任务'}</th></tr></thead><tbody>{browserRows.filter(row => !management || (row.account?.name || row.observed?.name || '').toLowerCase().includes(search.toLowerCase())).map(row => {
      const { account, observed } = row;
      const observationFresh = !!observed && observedIsFresh(observed);
      const accountFresh = !!account && account.data_stale === false && !!account.observed_at;
      const candidates = [observed, account].filter((item): item is ObservedAccount | Account => !!item && (!account?.phase || (item.phase === account.phase && !('phase_stale' in item && item.phase_stale))) && !!item.observed_at && [item.balance,item.equity,item.unrealized_pnl].some(value => value != null));
      const values = candidates.sort((a,b) => dateValue(b.observed_at)-dateValue(a.observed_at))[0] || null;
      const pendingUpdate = !!values && (values === observed ? !observationFresh : !accountFresh);
      const available = mode === 'browser' && !!account && eligible.some(item => item.id === account.id);
      const job = account ? accountJob(account.id) : undefined;
      const position = account ? data?.positions.find(item => item.account_id === account.id) : undefined;
      const excluded = account?.execution_excluded || observed?.execution_excluded;
      const executing = !excluded && account?.execution_mode === 'execute';
      const name = account?.name || observed?.name || '未识别账户';
      const label = excluded ? '永久排除执行' : account?.archived ? '已归档' : account?.category === 'closed' ? '已关闭' : account?.retired_failed || account?.category === 'failed' ? '评估失败' : job?.status === 'unknown' ? '结果待核验' : job ? '等待确认' : observed?.ambiguous ? '名称重复，无法区分' : account?.phase_pending ? '阶段同步中' : account?.status === 'locked' ? '已锁定' : account?.status === 'passed' ? '已达目标' : !account && !values ? '等待读取完成' : !values ? '资金待更新' : account?.daily_entry_used ? '本交易日已开仓' : '已同步';
      return <tr key={row.key} className={account && selected.includes(account.id) && available ? 'selected-row' : pendingUpdate ? 'observation-stale' : ''}>
        <td><input aria-label={`选择 ${name}`} type="checkbox" disabled={!available || strategyRunning} checked={!!account && selected.includes(account.id) && available} onChange={() => account && toggleSelection(account.id)} /></td>
        <td><div className="observed-account-name"><span className="account-avatar"><Wallet size={13} /></span><div><strong>{name}</strong><small>{({ eval: '考核账户', funded: '资金账户', passed: '已通过', failed: '已失败', closed: '已关闭', default: '默认账户' } as Record<string, string>)[account?.category || observed?.category || ''] || account?.category || observed?.category || '账户类型待识别'}{observed?.current ? ' · 当前页面' : ''}</small>{account && ArchiveAction(account)}</div></div></td>
        <td><button className="phase-badge" disabled={!account} aria-label={`查看 ${name} 阶段明细`} onClick={() => account && setPhaseDetailId(account.id)}>{account?.phase || observed?.phase || '待识别'}</button>{account?.phase_pending && <small className="cell-subtitle">→ {account.phase_pending.phase} 同步中</small>}</td>
        <td><span className={`status-pill ${executing ? 'positive' : 'muted'}`}><i />{executing ? '执行' : '只读'}</span></td>
        <td className="numeric value">{money(values?.balance)}</td><td className="numeric value">{money(values?.equity)}</td>
        <td className={`numeric ${values?.unrealized_pnl == null ? 'dim' : values.unrealized_pnl >= 0 ? 'positive' : 'negative'}`}>{signed(values?.unrealized_pnl)}</td>
        {DailyRealizedCell(account)}
        <td className={`numeric phase-realized-pnl ${(account?.phase_realized_pnl ?? 0) >= 0 ? 'positive' : 'negative'}`} title="当前阶段已记录的平仓盈亏；阶段切换独立统计">{signed(account?.phase_realized_pnl)}</td>
        {(['daily_loss','drawdown','goal'] as const).map(key => CapitalMetricCell(key,account,observed))}
        <td><span className={`status-pill ${job?.status === 'unknown' || account?.status === 'locked' ? 'negative' : !values ? 'muted' : 'neutral'}`}><i />{label}</span>{pendingUpdate && <span className="status-pill pending-update" title="保留上次读取的账户信息，等待页面更新">待更新</span>}{(account?.lock_reason || observed?.read_error) && <small className="observation-read-error" title={account?.lock_reason || observed?.read_error || ''}>{account?.lock_reason || observed?.read_error}</small>}<small className="browser-read-time">{(observed?.observed_at || account?.observed_at) ? dateText(values?.observed_at || observed?.observed_at || account?.observed_at || 0, true) : '尚无有效读数'}</small></td>
        <td>{account ? StrategyLockControl(account) : <span className="dim">—</span>}</td><td>{account?.archived ? <span className="dim" title={account.archived_at ? dateText(account.archived_at) : undefined}>{account.retired_failed ? '已归档 · 永久停用' : '已手动归档'}</span> : account?.retired_failed ? <span className="dim">已停用</span> : account?.status === 'locked' ? <div className="browser-account-actions"><button className="button small danger-outline" disabled={!!busy} onClick={() => setConfirmAction({ title: `核对 ${name} 的账户状态？`, description: '请先在 Vest 人工处理所有实际持仓及挂单，保持页面在线且明确空仓。核对只清除本地不确定状态，不会自动恢复策略。', run: () => void perform('/api/bridge/reconcile', { account_id: account.id, acknowledge: true }, '人工核对完成，请查看账户状态，策略未自动恢复') })}>人工核对</button></div> : job ? <span className="dim">{job.type === 'open' ? '开仓待确认' : '平仓待确认'}</span> : position ? <span className={`position-badge ${position.side === 'buy' ? 'positive' : 'negative'}`}>{position.side === 'buy' ? '多' : '空'} {position.quantity}</span> : <span className="dim">{!account || !values ? '—' : '无工具持仓'}</span>}</td>
      </tr>;
    })}</tbody></table></div> : archivedAccountCount > 0 ? <div className="empty-state compact-empty"><Archive size={25} /><strong>账户已归档</strong><p>勾选「显示已归档」查看原始账户信息与记录。</p></div> : <div className="observation-empty"><span className="observation-empty-icon"><Eye size={27} /></span><h3>尚未收到 Vest 页面数据</h3><p>在已登录的 Vest 页面打开插件，粘贴配对码后点击「读取账户」。<br />账户会自动加入列表，通过插件「只读 / 执行」开关控制交易权限。</p><div className="inline-buttons"><button className="button primary small" disabled={!!busy} onClick={() => void copyPairingCode()}><Copy size={13} />一键复制配对码</button><button className="button ghost small" onClick={() => setPage('bridge')}><Link2 size={13} />查看连接步骤</button></div></div>}
    <div className="observation-note"><ShieldCheck size={13} /><span>主账户永久排除所有执行，仅展示信息。只读模式同步账户信息；执行模式允许其余所选账户接收交易任务。账户识别、页面状态及成交结果由系统自动核验，数据缺失或结果未知时暂停。现金余额为页面净值减去浮动盈亏。阶段从页面识别，点击阶段可查看独立记录。最大日亏损、最大回撤和阶段目标按当前阶段的 Vest 页面原值同步。阶段切换重置当日开仓额度与自动锁定，保留手动排除和归档。当日盈亏仅汇总本工具已记录的平仓历史，按美东 17:00 日切。</span></div>
  </>;

  const ObservedAccountsPanel = ({ management = false }: { management?: boolean } = {}) => <section className="panel observed-account-panel" id="vest-page-accounts">
    <div className="panel-heading observed-panel-heading"><div><h2><Users size={16} />Vest 账户 <span className="count-badge">{browserRows.length}</span></h2><p>读取后自动接入；真实执行权限只由插件模式开关控制。</p></div><div className="observation-actions">{management && <div className="search-input"><Search size={14} /><input aria-label="搜索账户名称" placeholder="搜索账户名称…" value={search} onChange={event => setSearch(event.target.value)} /></div>}<button className="button primary small" disabled={!!busy} onClick={() => void copyPairingCode()}><Copy size={13} />复制配对码</button><button className="icon-button" aria-label="同步已读取的账户结果" title="刷新显示；读取全部账户请在插件中操作" onClick={() => { void refresh(); void refreshObservation(); }}><RefreshCw size={14} /></button></div></div>
    {BrowserAccountTable({ management })}
  </section>;

  const BrowserStats = () => <section className="stats-grid browser-observation-stats">
    <div className="stat-card"><div className="stat-title">已读取账户净值 <Wallet size={15} /></div><div className="stat-value">{observedEquity.value == null ? '—' : <><span className="currency-symbol">$</span>{money(observedEquity.value)}</>}<span className="unit">USDC</span></div><div className="stat-foot"><span className="soft-label">{observedEquity.count} / {observedAccounts.length} 个账户有读数 · {observedEquity.pending} 待更新</span></div></div>
    <div className="stat-card"><div className="stat-title">已读取现金余额 <Wallet size={15} /></div><div className="stat-value">{observedBalance.value == null ? '—' : money(observedBalance.value)}<span className="unit">USDC</span></div><div className="stat-foot"><span className="soft-label">最后现金读数合计 · {observedBalance.pending} 个账户待更新</span></div></div>
    <div className="stat-card"><div className="stat-title">已读取浮动盈亏 <Activity size={16} /></div><div className={`stat-value ${observedUnrealized.value == null ? 'dim' : observedUnrealized.value >= 0 ? 'positive' : 'negative'}`}>{signed(observedUnrealized.value)}<span className="unit">USDC</span></div><div className="stat-foot"><i className={`live-dot ${freshObservedAccounts.length ? '' : 'inactive'}`} /><span className="soft-label">最后浮盈亏读数合计 · {observedUnrealized.pending} 待更新</span></div></div>
    <div className="stat-card"><div className="stat-title">已读取 Vest 账户 <Users size={16} /></div><div className="stat-value">{activeObservedAccounts.length.toString().padStart(2, '0')}<span className="accounts-unit">个账户</span></div><div className="stat-foot"><span><i className="inline-dot" />{freshObservedAccounts.length} 已同步</span><span className="stat-divider" /><span className="soft-label">{activeObservedAccounts.length - freshObservedAccounts.length} 待更新</span></div></div>
  </section>;

  const AccountTable = ({ management = false }: { management?: boolean }) => <div className="table-scroll"><table className="account-table"><thead><tr><th className="check-cell"><input aria-label="选择全部可交易账户" type="checkbox" checked={eligible.length > 0 && selectedEligible.length === eligible.length} onChange={selectAll} /></th><th>账户名称</th><th>状态</th><th className="numeric">账户净值 <span>USDC</span></th><th className="numeric">{mode === 'browser' ? '余额变化' : '已实现盈亏'}</th><th className="numeric">浮动盈亏</th><th className="numeric daily-pnl-heading" title={dailyPnlTitle}>当日已实现盈亏 <span>USDC</span><small>美东 17:00 日切</small></th><th>盈利目标进度</th><th>策略锁定</th><th className="numeric">{management ? '管理' : '持仓'}</th></tr></thead><tbody>{accounts.filter(a => !management || a.name.toLowerCase().includes(search.toLowerCase())).map((account, index) => {
    const progress = account.profit_target && account.profit_target > 0 ? Math.max(0, Math.min(100, (account.realized_pnl ?? 0) / account.profit_target * 100)) : 0;
    const position = positions.find(p => p.account_id === account.id);
    const available = eligible.some(a => a.id === account.id);
    const job = accountJob(account.id);
    return <tr key={account.id} className={selected.includes(account.id) ? 'selected-row' : ''}><td><input aria-label={`选择 ${account.name}`} type="checkbox" disabled={!available} checked={selected.includes(account.id) && available} onChange={() => toggleSelection(account.id)} /></td><td><div className="account-name"><div className={`account-avatar avatar-${index % 4}`}>{account.name.slice(0, 1).toUpperCase()}</div><div><strong>{account.name}</strong><small>{account.id.slice(0, 12)} · 模拟账户</small></div></div></td><td><span className={`status-pill ${job?.status === 'unknown' ? 'negative' : job ? 'neutral' : !account.enabled ? 'muted' : account.status === 'locked' ? 'negative' : account.status === 'passed' ? 'positive' : 'neutral'}`}><i />{job?.status === 'unknown' ? '结果未知' : job ? '等待确认' : !account.enabled ? '已停用' : account.status === 'active' && account.daily_entry_used ? '本交易日已开仓' : statusNames[account.status] || account.status}</span></td><td className="numeric value">{money(account.equity)}</td><td className={`numeric ${(account.realized_pnl ?? 0) >= 0 ? 'positive' : 'negative'}`}>{signed(account.realized_pnl)}</td><td className={`numeric ${account.unrealized_pnl == null || account.unrealized_pnl === 0 ? 'dim' : (account.unrealized_pnl ?? 0) > 0 ? 'positive' : 'negative'}`}>{account.unrealized_pnl === 0 ? '—' : signed(account.unrealized_pnl)}</td>{DailyRealizedCell(account)}<td><div className="goal-cell"><span>{money(progress, 1)}%<small>{money(account.profit_target, 0)}</small></span><div className="progress"><i style={{ width: `${progress}%` }} /></div></div></td><td>{StrategyLockControl(account)}</td><td className="numeric">{management ? <div className="row-actions"><button className={`icon-button ${account.enabled ? 'positive' : ''}`} title={account.enabled ? '停用账户' : '启用账户'} aria-label={`${account.enabled ? '停用' : '启用'} ${account.name}`} disabled={!!busy || account.execution_excluded || !!position || !!job} onClick={() => void perform(`/api/accounts/${account.id}/toggle`, { enabled: !account.enabled }, '账户状态已更新')}><Power size={14} /></button><button className="icon-button danger-hover" aria-label={`删除 ${account.name}`} title={position || job ? '有持仓或待确认操作时无法删除' : '删除账户'} disabled={!!busy || !!position || !!job} onClick={() => setConfirmAction({ title: `删除 ${account.name}？`, description: '此操作移除账户。只有没有持仓和待确认订单的账户才可删除。', run: () => void perform(`/api/accounts/${account.id}`, undefined, '账户已删除', 'DELETE') })}><Trash2 size={14} /></button></div> : job ? <span className={`status-pill ${job.status === 'unknown' ? 'negative' : 'neutral'}`}>{job.status === 'unknown' ? '结果未知 · 待核验' : job.type === 'open' ? '开仓待确认' : '平仓待确认'}</span> : position ? <span className={`position-badge ${position.side === 'buy' ? 'positive' : 'negative'}`}>{position.side === 'buy' ? '多' : '空'} {position.quantity}</span> : <span className="dim">空仓</span>}</td></tr>;
  })}</tbody></table>{!accounts.length && <div className="empty-state"><Users size={28} /><strong>还没有模拟账户</strong><p>添加模拟账户，开始建立你的交易工作空间。</p><button className="button primary small" onClick={() => setShowAdd(true)}><Plus size={14} />添加账户</button></div>}</div>;

  const PositionsTable = () => <div className="table-scroll"><table><thead><tr><th>账户 / 合约</th><th>方向 / 数量</th><th className="numeric">开仓价格</th><th className="numeric">标记价格</th><th className="numeric">浮动盈亏</th><th className="numeric">止盈 / 止损 USDC</th><th>状态</th><th className="numeric">操作</th></tr></thead><tbody>{positions.map(position => <tr key={position.id}><td><strong>{position.account_name}</strong><small className="cell-subtitle">{position.symbol}</small></td><td><span className={position.side === 'buy' ? 'positive' : 'negative'}>{position.side === 'buy' ? '做多' : '做空'}</span> <span className="dim">× {position.quantity}</span></td><td className="numeric">{money(position.entry_price)}</td><td className="numeric">{money(position.mark_price)}</td><td className={`numeric value ${(position.unrealized_pnl ?? 0) >= 0 ? 'positive' : 'negative'}`}>{signed(position.unrealized_pnl)}</td><td className="numeric"><span className="positive">{position.take_profit == null ? '未设置' : money(position.take_profit)}</span><span className="dim"> / </span><span className="negative">{position.stop_loss == null ? '未设置' : money(position.stop_loss)}</span></td><td><span className="status-pill neutral">{statusNames[position.status] || position.status}</span></td><td className="numeric"><button className="button small ghost" disabled={!!busy || ['closing', 'pending_close', 'pending_open', 'unknown'].includes(position.status) || (mode === 'browser' && !accounts.find(account => account.id === position.account_id)?.executable)} onClick={() => setConfirmAction({ title: `平仓 ${position.account_name}？`, description: `${position.symbol} ${position.side === 'buy' ? '多' : '空'}单 ${position.quantity}，按当前可执行价格平仓。`, run: () => void perform(`/api/positions/${position.id}/close`, {}, '平仓指令已提交') })}>平仓</button></td></tr>)}</tbody></table>{!positions.length && <div className="empty-state compact-empty"><Activity size={25} /><strong>当前没有持仓</strong><p>选择账户后，在下单面板提交你的第一笔订单。</p></div>}</div>;

  const HistoryFilters = () => <div className="history-filters"><select aria-label="筛选交易账户" value={historyAccount} onChange={event => setHistoryAccount(event.target.value)}><option value="all">全部账户</option>{(mode === 'browser' ? discoveredBrowserAccounts : accounts).map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select><select aria-label="筛选交易时间" value={historyDays} onChange={event => setHistoryDays(Number(event.target.value))}><option value={7}>最近 7 天</option><option value={30}>最近 30 天</option><option value={0}>全部时间</option></select><select aria-label="筛选交易盈亏" value={historyResult} onChange={event => setHistoryResult(event.target.value)}><option value="all">全部盈亏</option><option value="profit">盈利交易</option><option value="loss">亏损交易</option></select><button className="button ghost small" onClick={exportHistory}><Download size={14} />导出 CSV</button></div>;
  const HistoryTable = () => <>{mode === 'browser' && <div className="history-method-note"><Eye size={14} /><span>浏览器记录以开平仓间的现金余额差计量，含费用及其他资金变动，不等同于精确成交损益；平仓价格为网页观察价。CSV 按相同口径导出。</span></div>}{HistoryFilters()}<div className="table-scroll"><table><thead><tr><th>平仓时间 <span>UTC+8</span></th><th>账户 / 合约</th>{mode === 'browser' && <th>阶段</th>}<th>方向</th><th className="numeric">数量</th><th className="numeric">开仓价</th><th className="numeric">{mode === 'browser' ? '平仓观察价' : '平仓价'}</th><th className="numeric">{mode === 'browser' ? '余额变化 USDC' : '净盈亏 USDC'}</th><th>平仓原因</th></tr></thead><tbody>{[...filteredHistory].sort((a, b) => dateValue(b.closed_at) - dateValue(a.closed_at)).map(trade => <tr key={trade.id}><td className="dim mono">{dateText(trade.closed_at, true)}</td><td><strong>{trade.account_name}</strong><small className="cell-subtitle">{trade.symbol}</small></td>{mode === 'browser' && <td>{trade.phase || '未识别'}</td>}<td className={trade.side === 'buy' ? 'positive' : 'negative'}>{trade.side === 'buy' ? '做多' : '做空'}</td><td className="numeric">{trade.quantity}</td><td className="numeric">{money(trade.entry_price)}</td><td className="numeric">{money(trade.exit_price)}</td><td className={`numeric value ${trade.pnl >= 0 ? 'positive' : 'negative'}`}>{signed(trade.pnl)}</td><td><span className="reason-badge">{reasonNames[trade.reason] || trade.reason}</span></td></tr>)}</tbody></table>{!filteredHistory.length && <div className="empty-state compact-empty"><BookOpen size={25} /><strong>此范围内暂无交易</strong><p>调整账户、日期或盈亏筛选查看其它记录。</p></div>}</div></>;

  const Stats = () => mode === 'browser' ? BrowserStats() : <section className="stats-grid"><div className="stat-card"><div className="stat-title">账户总净值 <Wallet size={15} /></div><div className="stat-value"><span className="currency-symbol">$</span>{staleTotals ? '—' : money(equity)}<span className="unit">USDC</span></div><div className="stat-foot"><span className="soft-label">初始资金</span><span>{money(accounts.reduce((sum, a) => sum + (a.initial_balance ?? 0), 0))}</span></div></div><div className="stat-card"><div className="stat-title">累计已实现盈亏 <TrendingUp size={16} /></div><div className={`stat-value ${realized >= 0 ? 'positive' : 'negative'}`}>{signed(realized)}<span className="unit">USDC</span></div><div className="stat-foot"><span className={`mini-chip ${todayPnl >= 0 ? 'positive' : 'negative'}`}>{todayPnl >= 0 ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}{signed(todayPnl)}</span><span className="soft-label">今日已实现</span></div></div><div className="stat-card"><div className="stat-title">当前浮动盈亏 <Activity size={16} /></div><div className={`stat-value ${unrealized >= 0 ? 'positive' : 'negative'}`}>{staleTotals ? '—' : signed(unrealized)}<span className="unit">USDC</span></div><div className="stat-foot"><i className={`live-dot ${positions.length ? '' : 'inactive'}`} /><span className="soft-label">{positions.length} 笔持仓 · {staleTotals ? '存在离线账户' : '每秒同步'}</span></div></div><div className="stat-card"><div className="stat-title">管理账户 <Users size={16} /></div><div className="stat-value">{accounts.length.toString().padStart(2, '0')}<span className="accounts-unit">个账户</span></div><div className="stat-foot"><span><i className="inline-dot" />{eligible.length} 可用</span><span className="stat-divider" /><span className="soft-label">{accounts.filter(a => a.status === 'passed').length} 已达目标</span><button className="inline-icon" aria-label="进入账户管理" onClick={() => setPage('accounts')}><ArrowUpRight size={15} /></button></div></div></section>;

  const MarketCard = () => <section className="panel market-panel"><div className="market-header"><div className="instrument"><span className="instrument-icon">NQ</span><div><h2>NQ-PERP <span className="contract-pill">永续</span></h2><small>Nasdaq 100 · {mode === 'paper' ? '模拟行情' : '浏览器观测'}</small></div></div><div className="market-price"><strong>{data?.market?.price ? money(data.market.price) : '—'}</strong><span className={(data?.market?.change_pct || 0) >= 0 ? 'positive' : 'negative'}>{data?.market?.change_pct == null ? '—' : `${data.market.change_pct >= 0 ? '+' : ''}${money(data.market.change_pct)}%`}</span></div><div className="market-stat"><small>区间最高</small><span>{data?.market?.high ? money(data.market.high) : '—'}</span></div><div className="market-stat"><small>区间最低</small><span>{data?.market?.low ? money(data.market.low) : '—'}</span></div></div><div className="chart-toolbar"><div className="timeframes">{[[1, '1m'], [5, '5m'], [15, '15m'], [60, '1h']].map(([value, label]) => <button key={value} className={period === value ? 'active' : ''} onClick={() => setPeriod(Number(value))}>{label}</button>)}</div><span className="chart-type"><BarChart3 size={14} />K 线</span><span className="chart-source"><i className={`live-dot ${error || (mode === 'browser' && data?.market.source === 'unavailable') ? 'inactive' : ''}`} />{mode === 'paper' ? '本地模拟数据' : data?.market.source === 'unavailable' ? '浏览器离线 · 留存采样' : '连接后采样 · 非官方历史'}</span></div><div className="chart-ohlc"><span>O <b>{money(data?.candles.at(-1)?.open)}</b></span><span>H <b>{money(data?.candles.at(-1)?.high)}</b></span><span>L <b>{money(data?.candles.at(-1)?.low)}</b></span><span>C <b className={(data?.candles.at(-1)?.close || 0) >= (data?.candles.at(-1)?.open || 0) ? 'positive' : 'negative'}>{money(data?.candles.at(-1)?.close)}</b></span></div>{data?.candles.length ? <CandleChart candles={data.candles} interval={period} /> : <div className="empty-chart"><Activity size={28} /><span>{mode === 'paper' ? '等待模拟引擎行情数据' : '等待浏览器价格采样 · 非官方历史 K 线'}</span></div>}<div className="chart-footer"><a href="https://www.tradingview.com/lightweight-charts/" target="_blank" rel="noreferrer">TradingView Lightweight Charts™</a><span>UTC+8 <span className="dim">·</span> {mode === 'paper' ? 'SIMULATED' : 'LOCAL SAMPLED · VOL UNKNOWN'}</span></div></section>;

  const OrderPanel = () => <section className="panel order-panel"><div className="panel-heading"><h2>下单面板</h2><span className="outline-badge">市价单</span></div><form onSubmit={submitOrder}><div className="side-selector"><button type="button" className={side === 'buy' ? 'active long' : ''} onClick={() => setSide('buy')}><ArrowUpRight size={15} />买入 / 做多</button><button type="button" className={side === 'sell' ? 'active short' : ''} onClick={() => setSide('sell')}><ArrowDownRight size={15} />卖出 / 做空</button></div><div className="order-account-info"><span><Users size={14} />下单账户</span><button type="button" onClick={() => { setTableTab('accounts'); (document.getElementById('account-section') || document.getElementById('vest-page-accounts'))?.scrollIntoView({ behavior: 'smooth', block: 'center' }); }}>{selectedEligible.length} 个已选<ChevronDown size={13} /></button></div><Field label={mode === 'browser' ? '微型合约数量' : '合约数量'} suffix={mode === 'browser' ? '每个账户 · Micro' : '每个账户 · Vest 数量'}><div className="number-input"><input aria-label="下单合约数量" type="number" min={mode === 'browser' ? 1 : 0.0001} step={mode === 'browser' ? 1 : 'any'} required value={quantity} onChange={event => setQuantity(Number(event.target.value))} /><span>{mode === 'browser' ? 'Micro' : 'Vest 单位'}</span></div>{mode === 'browser' && <small>1 Micro = 2 Vest 单位；持仓与历史数量按 Vest 单位显示。</small>}</Field><div className="order-divider" /><div className="section-eyebrow"><ShieldCheck size={14} />止盈 / 止损 <span>每账户 · USDC</span></div><div className="two-columns"><div className="field"><span className="field-label">止盈</span><div className="no-take-profit">不设置 · 按账户目标结束</div></div><Field label="止损金额"><div className="number-input"><span className="negative">−</span><input aria-label="每账户止损金额" type="number" min="0.01" step="any" required value={stopLoss} onChange={event => setStopLoss(Number(event.target.value))} /></div></Field></div><div className="order-summary"><div><span>订单数量</span><strong>{selectedEligible.length} 个账户 × {quantity}</strong></div><div><span>总止损预算</span><strong className="negative">{money(selectedEligible.length * stopLoss)} USDC</strong></div><div><span>止盈设置</span><strong>不设置</strong></div></div><button className={`button order-button ${side === 'buy' ? 'buy-button' : 'sell-button'}`} disabled={!!busy || !!error || !selectedEligible.length || strategyRunning || quantity <= 0 || stopLoss <= 0} type="submit">{busy === '/api/orders' ? <LoaderCircle size={17} className="spin" /> : <Plus size={17} />}{mode === 'paper' ? '模拟' : ''}{side === 'buy' ? '买入 / 做多' : '卖出 / 做空'}<span>{selectedEligible.length} 账户</span></button><p className="order-note"><ShieldCheck size={12} />{mode === 'paper' ? '模拟撮合 · 1 数量每点 1 USDC' : '真实网页操作 · 等待页面确认成交'}</p></form></section>;

  const AccountSection = () => <section className="panel account-panel" id={mode === 'browser' ? 'vest-page-accounts' : 'account-section'}><div className="account-panel-heading"><div className="panel-tabs"><button className={tableTab === 'accounts' ? 'active' : ''} onClick={() => setTableTab('accounts')}>{mode === 'browser' ? 'Vest 账户' : '账户总览'} <span>{mode === 'browser' ? browserRows.length : accounts.length}</span></button><button className={tableTab === 'positions' ? 'active' : ''} onClick={() => setTableTab('positions')}>当前持仓 <span>{positions.length}</span></button><button className={tableTab === 'history' ? 'active' : ''} onClick={() => setTableTab('history')}>交易历史</button></div><div className="account-tools">{tableTab === 'accounts' && <><span className="selection-count">已选 <b>{selectedEligible.length}</b> 个账户</span>{mode === 'paper' ? <button className="button ghost small" onClick={() => setShowAdd(true)}><Plus size={14} />添加账户</button> : <span className={`status-pill ${executionAccounts.length ? 'positive' : 'muted'}`}>{executionAccounts.length ? '插件执行模式' : '插件只读模式'}</span>}</>}{tableTab === 'positions' && positions.length > 0 && <button className="button small danger-outline" disabled={!!busy || (mode === 'browser' && !executionAccounts.length)} onClick={() => setConfirmAction({ title: '平掉全部持仓？', description: `为当前模式下的 ${positions.length} 笔持仓提交平仓指令。未确认的浏览器订单需要人工核验。`, run: () => void perform('/api/positions/close-all', {}, '已提交平仓请求，请核对持仓及页面回执') })}>全部平仓</button>}</div></div>{tableTab === 'accounts' ? mode === 'browser' ? BrowserAccountTable() : AccountTable({}) : tableTab === 'positions' ? PositionsTable() : HistoryTable()}<div className="table-footer"><span><i className={`live-dot ${error ? 'inactive' : ''}`} />{error ? '同步中断' : '数据每秒自动同步'}</span><span>{tableTab === 'accounts' ? `共 ${mode === 'browser' ? browserRows.length : accounts.length} 个账户 · 金额以 USDC 计价` : tableTab === 'positions' ? '止盈止损按每个账户独立执行' : `当前筛选共 ${filteredHistory.length} 笔成交`}</span></div></section>;

  const dailyPnl = useMemo(() => {
    const map = new Map<string, number>();
    [...filteredHistory].sort((a, b) => dateValue(a.closed_at) - dateValue(b.closed_at)).forEach(t => { const key = new Date(dateValue(t.closed_at)).toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit' }); map.set(key, (map.get(key) || 0) + t.pnl); });
    return [...map.entries()].slice(-14);
  }, [filteredHistory]);
  const maxDaily = Math.max(1, ...dailyPnl.map(([, value]) => Math.abs(value)));

  return <div className="app-shell"><aside className="sidebar"><button className="brand" onClick={() => setPage('dashboard')} aria-label="返回交易工作台"><span className="brand-mark"><i /><i /><i /></span><span>VEST<span className="brand-sub">CONTROL</span></span><span className="version-badge">BETA</span></button><div className="workspace-label">交易工作空间</div><nav>{([{ id: 'dashboard', label: '交易工作台', icon: LayoutDashboard }, { id: 'accounts', label: '账户管理', icon: Users }, { id: 'analytics', label: '盈亏分析', icon: BarChart3 }, { id: 'strategy', label: '自动策略', icon: Zap }, { id: 'backtest', label: '策略回测', icon: Activity }, { id: 'backtest-history', label: '回测历史', icon: Search }, { id: 'bridge', label: '浏览器连接', icon: Link2 }] as const).map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => setPage(item.id)}><item.icon size={18} /><span>{item.label}</span>{item.id === 'strategy' && strategyRunning && <i className="live-dot" />}{item.id === 'bridge' && mode === 'browser' && <span className="nav-count">{freshObservedAccounts.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="engine-card"><div><span className="engine-symbol"><Zap size={15} /></span><strong>自动化交易引擎</strong></div><p>{strategyRunning ? `正在执行第 ${data?.strategy.batch_number} 批账户` : '规则明确，交易有序。'}</p><button onClick={() => setPage('strategy')}>{strategyRunning ? '查看运行状态' : '配置你的策略'}<ArrowRight size={14} /></button></div><button className="sidebar-help" onClick={() => setPage('bridge')}><CircleHelp size={17} /><span>连接与使用指南</span><ArrowUpRight size={14} /></button><div className="user-profile"><span className="user-avatar">RB</span><div><strong>本地工作空间</strong><small>CoinMachine / Vest</small></div><span className="local-badge">LOCAL</span></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb"><span>工作空间</span><ChevronRight size={13} /><strong>{pageInfo[page].title}</strong></div><div className="topbar-right"><div className="mode-switch"><button className={mode === 'paper' ? 'active' : ''} disabled={(page === 'backtest' || page === 'backtest-history') || !!busy || !data} onClick={() => switchMode('paper')}>模拟交易</button><button className={mode === 'browser' ? 'active browser' : ''} disabled={(page === 'backtest' || page === 'backtest-history') || !!busy || !data} onClick={() => switchMode('browser')}>浏览器交易</button></div><span className={`connection-indicator ${error ? 'negative' : ''}`}>{error ? <WifiOff size={13} /> : <Wifi size={13} />}{error ? '连接中断' : data ? '引擎已连接' : '连接中'}</span><button className="icon-button refresh-button" title="立即同步" aria-label="立即同步" onClick={() => { void refresh(); toast('正在同步账户状态'); }}><RefreshCw size={16} /></button></div></header><main><div className="page-heading"><div><div className="page-eyebrow">VEST CONTROL <span>/</span> {page === 'dashboard' ? 'OVERVIEW' : page.toUpperCase()}</div><h1>{pageInfo[page].title}</h1><p>{pageInfo[page].subtitle}</p></div><div className="heading-actions"><span className="clock"><Clock3 size={13} />{new Date(now).toLocaleTimeString('en-GB', { timeZone: 'Asia/Shanghai' })}<small>UTC+8</small></span>{page !== 'bridge' && page !== 'backtest' && page !== 'backtest-history' && <button className="button primary" onClick={() => page === 'strategy' ? document.getElementById('strategy-form')?.scrollIntoView({ behavior: 'smooth' }) : mode === 'browser' ? setPage('bridge') : setShowAdd(true)}>{page === 'strategy' ? <Settings2 size={15} /> : mode === 'browser' ? <Link2 size={15} /> : <Plus size={15} />}{page === 'strategy' ? '策略参数' : mode === 'browser' ? '插件连接' : '添加账户'}</button>}</div></div>{error && <div className="error-banner"><WifiOff size={16} /><span>本地交易服务连接中断：{error}。请确认已运行 npm run dev。</span><button onClick={() => void refresh()}>重新连接</button></div>}{mode === 'browser' && page !== 'bridge' && page !== 'backtest' && page !== 'backtest-history' && <div className="mode-banner"><Eye size={15} /><span>{executionAccounts.length ? `插件处于执行模式 · ${executionAccounts.length} 个账户可接收交易任务` : '插件处于只读模式 · 在插件切换「执行」即可启用交易'}</span><button onClick={() => setPage('bridge')}>连接管理<ArrowRight size={13} /></button></div>}{!data ? <div className="loading-state"><LoaderCircle size={32} className="spin" /><h2>正在连接本地交易服务</h2><p>账户、行情与策略状态将在连接后显示。</p><code>npm run dev</code></div> : <>
      {page === 'dashboard' && <>{Stats()}<div className="trading-grid">{MarketCard()}{OrderPanel()}</div>{AccountSection()}<div className="workspace-footer"><span><ShieldCheck size={13} />本地运行 · {mode === 'paper' ? '模拟数据与真实账户完全隔离' : '真实执行需要浏览器页面在线'}</span><span>VEST CONTROL <span className="dim">v0.1.0</span></span></div></>}
      {page === 'accounts' && <>{Stats()}{mode === 'browser' ? ObservedAccountsPanel({ management: true }) : <section className="panel"><div className="panel-heading account-manage-heading"><div><h2>全部模拟账户 <span className="count-badge">{accounts.length}</span></h2><p>盈利目标、持仓状态与账户风控独立计算。</p></div><div className="search-input"><Search size={15} /><input placeholder="搜索账户名称…" aria-label="搜索账户名称" value={search} onChange={event => setSearch(event.target.value)} /></div></div>{AccountTable({ management: true })}<div className="table-footer"><span>已选 {selectedEligible.length} 个可交易账户</span><button className="text-button" onClick={() => { setPage('dashboard'); setTableTab('accounts'); }}>前往批量下单<ArrowRight size={13} /></button></div></section>}<div className="info-strip"><ShieldCheck size={17} /><div><strong>{mode === 'browser' ? '插件模式控制' : '账户级风控'}</strong><span>{mode === 'browser' ? '账户从 Vest 页面自动接入。在插件切换执行后，所选账户可提交订单；切回只读会撤销尚未发送的任务并停止后续执行。' : '达到盈利目标后退出交易池，触及最大亏损后锁定。已有持仓或待确认订单的账户无法删除。'}</span></div></div></>}
      {page === 'analytics' && <><section className="analytics-stat-grid"><div className="stat-card"><div className="stat-title">{mode === 'browser' ? '筛选期余额变化' : '筛选期净盈亏'} <TrendingUp size={16} /></div><div className={`stat-value ${filteredPnl >= 0 ? 'positive' : 'negative'}`}>{signed(filteredPnl)}</div><div className="stat-foot"><span className="soft-label">{mode === 'browser' ? 'USDC · 开平仓余额差' : 'USDC · 已实现'}</span></div></div><div className="stat-card"><div className="stat-title">交易胜率 <Target size={16} /></div><div className="stat-value">{money(winRate, 1)}<span className="unit">%</span></div><div className="stat-foot"><span className="soft-label">{winners} 笔盈利 / {filteredHistory.length} 笔成交</span></div></div><div className="stat-card"><div className="stat-title">盈利因子 <Activity size={16} /></div><div className="stat-value">{lossSum ? money(profitSum / lossSum) : profitSum ? '∞' : '—'}</div><div className="stat-foot"><span className="soft-label">总盈利 / 总亏损绝对值</span></div></div><div className="stat-card"><div className="stat-title">{mode === 'browser' ? '平均每笔余额变化' : '平均每笔盈亏'} <BarChart3 size={16} /></div><div className={`stat-value ${filteredPnl >= 0 ? 'positive' : 'negative'}`}>{filteredHistory.length ? signed(filteredPnl / filteredHistory.length) : '—'}</div><div className="stat-foot"><span className="soft-label">共 {filteredHistory.length} 笔交易</span></div></div></section><div className="analytics-charts"><section className="panel equity-panel"><div className="panel-heading"><div><h2>{mode === 'browser' ? '累计余额变化曲线' : '累计盈亏曲线'}</h2><p>{mode === 'browser' ? '开平仓余额差累计，含费用及其他资金变动' : '当前筛选条件下的已实现交易盈亏'}</p></div><span className="outline-badge">USDC</span></div><EquityChart trades={filteredHistory} /></section><section className="panel daily-panel"><div className="panel-heading"><h2>{mode === 'browser' ? '每日余额变化' : '每日盈亏'}</h2><span className="outline-badge">最近 14 个交易日</span></div><div className="daily-bars">{dailyPnl.length ? dailyPnl.map(([day, value]) => <div className="daily-bar-column" key={day} title={`${day}: ${signed(value)} USDC`}><span className={`daily-bar ${value >= 0 ? 'profit' : 'loss'}`} style={{ height: `${Math.max(4, Math.abs(value) / maxDaily * 155)}px` }} /><span>{day}</span></div>) : <div className="empty-state"><BarChart3 size={24} /><p>暂无交易记录</p></div>}</div><div className="bar-legend"><span><i className="legend-dot profit" />盈利</span><span><i className="legend-dot loss" />亏损</span></div></section></div><section className="panel"><div className="panel-heading"><h2>已平仓交易</h2><span className="dim">所有时间均为 UTC+8</span></div>{HistoryTable()}</section></>}
      {page === 'backtest-history' && <Suspense fallback={<p>正在加载回测历史…</p>}><BacktestHistory /></Suspense>}
      {page === 'backtest' && <Suspense fallback={<p>正在载入回测模块…</p>}><BacktestPanel /></Suspense>}
      {page === 'strategy' && <><div className="strategy-summary"><div className="strategy-summary-icon"><Zap size={23} /></div><div><h2>{(data.strategies || []).find(item => item.id === strategyForm.strategy_id)?.name || '随机下单'} <span className={`status-pill ${strategyRunning ? 'positive' : strategyUnresolved ? 'negative' : 'muted'}`}><i />{statusNames[data.strategy.status] || data.strategy.status}</span></h2><p>Live 优先、同阶段随机选账户 → 逐笔抖动下单 → 等待整批平仓 → 抖动间隔 → 下一批</p></div><div className="strategy-run-count"><strong>{String(data.strategy.batch_number || 0).padStart(2, '0')}</strong><span>已开始批次</span></div></div><div className="strategy-layout"><section className="panel strategy-config"><div className="panel-heading"><h2><SlidersHorizontal size={16} /> 执行参数</h2><span className="outline-badge">NQ-PERP</span></div><form id="strategy-form" onSubmit={startStrategy}><fieldset disabled={strategyRunning || !!busy || !strategyLoaded}><Field label="自动策略"><select aria-label="自动策略类型" value={strategyForm.strategy_id} onChange={event => updateStrategyForm({strategy_id:event.target.value})}>{(data.strategies || [{id:'random_entry',name:'随机下单'}]).map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><div className="form-section-label"><span>01</span>账户与仓位</div><div className="two-columns"><Field label="每批账户数量" suffix="n"><input aria-label="每批账户数量" required type="number" min="1" max={Math.max(1, strategyEligible.length)} step="1" value={strategyForm.batch_size} onChange={event => updateStrategyForm({ batch_size: Number(event.target.value) })} /></Field><div className="field"><span className="field-label" id="strategy-size-label">仓位大小</span><div className="position-size-options" role="group" aria-labelledby="strategy-size-label">{[25, 50, 75, 100].map(percent => <button key={percent} type="button" aria-label={`仓位大小 ${percent}%`} aria-pressed={strategyForm.size_percent === percent} className={strategyForm.size_percent === percent ? "selected" : ""} onClick={() => updateStrategyForm({ size_percent: percent })}>{percent}%</button>)}</div><small>{mode === "browser" ? "自动切到微型数量单位，使用 Vest 对应比例按钮计算仓位。" : "模拟：按账户净值比例、1 倍无杠杆折算数量。"}</small></div></div><Field label="下单方向"><select aria-label="策略下单方向" value={strategyForm.side} onChange={event => updateStrategyForm({ side: event.target.value as StrategyConfig['side'] })}><option value="random">随机做多 / 做空</option><option value="buy">仅做多</option><option value="sell">仅做空</option></select></Field><div className="form-section-label"><span>02</span>考核号止盈止损</div><div className="two-columns"><div className="field"><span className="field-label">止盈</span><div className="no-take-profit">不设置 · 按账户目标结束</div></div><Field label="止损金额" suffix="USDC"><input aria-label="策略止损金额" className="negative" required type="number" min="0.01" step="any" value={strategyForm.stop_loss} onChange={event => updateStrategyForm({ stop_loss: Number(event.target.value) })} /></Field></div><div className="strategy-stop-rule"><label className="strategy-stop-toggle"><input type="checkbox" aria-label="剩余最大回撤不足时不设置止损" checked={strategyForm.skip_stop_loss_on_low_drawdown} onChange={event => updateStrategyForm({skip_stop_loss_on_low_drawdown:event.target.checked})} /><span>剩余最大回撤小于阈值时不设置止损</span></label><Field label="剩余最大回撤阈值" suffix="USDC" hint={mode === 'browser' ? '开仓前按页面回撤上限减去已用回撤计算；读数不明时等待读取。' : '模拟账户按配置最大亏损加上当前净值与资金基准的差额计算。'}><input aria-label="剩余最大回撤阈值" type="number" min="0.01" step="any" required disabled={!strategyForm.skip_stop_loss_on_low_drawdown} value={strategyForm.drawdown_stop_loss_threshold} onChange={event => updateStrategyForm({drawdown_stop_loss_threshold:Number(event.target.value)})} /></Field><small>每次开仓前检查；等于或大于阈值时，仍按填写金额设置止损。</small></div><div className="form-section-label"><span>03</span>随机延迟 <span className="form-section-note">均匀随机 · 秒</span></div><Field label="账户之间的下单延迟"><div className="range-input"><input aria-label="账户下单最小延迟秒" required type="number" min="0" step="0.1" value={strategyForm.order_delay_min} onChange={event => updateStrategyForm({ order_delay_min: Number(event.target.value) })} /><span>至</span><input aria-label="账户下单最大延迟秒" required type="number" min={strategyForm.order_delay_min} step="0.1" value={strategyForm.order_delay_max} onChange={event => updateStrategyForm({ order_delay_max: Number(event.target.value) })} /><span>秒</span></div></Field><Field label="全部平仓后的批次间隔"><div className="range-input"><input aria-label="批次最小间隔秒" required type="number" min="0" step="0.1" value={strategyForm.batch_delay_min} onChange={event => updateStrategyForm({ batch_delay_min: Number(event.target.value) })} /><span>至</span><input aria-label="批次最大间隔秒" required type="number" min={strategyForm.batch_delay_min} step="0.1" value={strategyForm.batch_delay_max} onChange={event => updateStrategyForm({ batch_delay_max: Number(event.target.value) })} /><span>秒</span></div></Field><LiveStrategySettings value={strategyForm} onChange={updateStrategyForm} /></fieldset><p className={`form-footnote strategy-save-status ${strategySave.status === 'error' ? 'negative' : ''}`} role="status" aria-live="polite">{strategySave.status === 'loading' ? '正在读取已保存参数…' : strategySave.status === 'upgrade' ? '请在持仓处理完成后重启本地服务，以启用参数保存和回撤止损规则。' : strategySave.status === 'saving' ? '正在保存参数…' : strategySave.status === 'error' ? `参数未保存：${strategySave.error}` : '参数已自动保存'}{strategySave.status === 'error' && <button type="button" className="text-button" onClick={() => saveStrategyForm(strategyFormRef.current)}>重试保存</button>}</p><div className="strategy-rule"><ShieldCheck size={16} /><p>主账户永久排除所有执行，不受每日解锁影响。每账户每交易日只开一单（美东 20:00 日切，与日亏损重置对齐）；交易结束锁定至下一次美东 20:00 自动解锁；Live 默认锁定需单独解锁。考核号不设止盈，按账户目标结束；Live 使用独立参数。已有持仓继续保护，本批全部确认结束才进入下一批；剩余未锁定账户不足 n 个时结束。</p></div><div className="strategy-buttons"><button type="submit" className="button primary" disabled={!!busy || !!error || !strategyLoaded || strategySave.status === 'saving' || strategyRunning || strategyUnresolved || selectedStrategy.length < strategyForm.batch_size}><Play size={16} />{strategyRunning ? '策略运行中' : strategyNeedsVerification ? '待人工核验' : strategyUnresolved ? (positions.length ? '等待当前持仓结束' : '等待交易确认') : '启动本轮策略'}</button><button type="button" className="button danger-outline" disabled={!!busy || (!strategyRunning && !strategyPaused)} onClick={() => void perform('/api/strategy/stop', {}, '策略已停止新增订单，已有持仓继续保护')}><Square size={13} />停止</button></div><p className="form-footnote">{mode === 'browser' ? '插件切回只读会停止执行；已提交到 Vest 的订单和原生止盈止损需在页面查看。' : '停止只中止新增订单，不会自动平掉已有持仓。'}</p></form></section><div className="strategy-monitor"><section className="panel"><div className="panel-heading"><h2>账户池</h2><button className="text-button" onClick={selectStrategyAll} disabled={strategyRunning}>{selectedStrategy.length === strategyEligible.length ? '取消全选' : '选择全部'}</button></div><div className="pool-summary"><span>已选 <strong>{selectedStrategy.length}</strong> 个账户 · {accounts.filter(account => account.strategy_locked).length} 已锁定</span><span>预计 <strong>{Math.floor(selectedStrategy.length / Math.max(1, strategyForm.batch_size))}</strong> 个完整批次</span></div><div className="account-pool">{accounts.map((account, index) => <label className={`pool-account ${selectedStrategy.includes(account.id) ? 'selected' : ''}`} key={account.id}><input type="checkbox" checked={selected.includes(account.id) && strategyEligible.some(a => a.id === account.id)} disabled={strategyRunning || !strategyEligible.some(a => a.id === account.id)} onChange={() => toggleSelection(account.id)} /><span className={`account-avatar avatar-${index % 4}`}>{account.name.slice(0, 1)}</span><span><strong>{account.name}</strong><small>{account.execution_excluded ? '主账户永久排除所有执行' : account.retired_failed ? (account.category === 'closed' ? '已关闭 · 永久停用' : '评估失败 · 永久停用') : account.strategy_locked ? account.strategy_lock_reason : account.daily_entry_used ? '本交易日已开仓 · 不再开新单' : `${money(account.equity)} USDC`}</small></span><span className="pool-strategy-lock">{StrategyLockControl(account, true)}</span><span className={(account.realized_pnl ?? 0) >= 0 ? 'positive' : 'negative'}>{signed(account.realized_pnl)}</span></label>)}{!accounts.length && <div className="empty-state compact-empty"><Users size={25} /><p>{mode === 'browser' ? '在插件中读取账户，即可自动加入账户池' : '先添加模拟账户'}</p></div>}</div></section><section className="panel batch-state"><div className="panel-heading"><h2>当前执行状态</h2><span className={`status-pill ${strategyRunning ? 'positive' : 'muted'}`}><i />{statusNames[data.strategy.status]}</span></div><div className="batch-numbers"><div><strong>{data.strategy.batch_number || '—'}</strong><small>当前批次</small></div><div><strong>{count(data.strategy.completed_accounts)}</strong><small>已完成账户</small></div><div><strong>{count(data.strategy.remaining_accounts)}</strong><small>待处理账户</small></div></div>{!!data.strategy.next_action_at && strategyRunning && <div className="next-action"><Clock3 size={14} /><span>下一操作倒计时</span><strong>{Math.max(0, Math.ceil((dateValue(data.strategy.next_action_at) - now) / 1000))} s</strong></div>}<div className="batch-account-chips">{data.strategy.batch_account_ids?.map(id => <span key={id}><i className={`inline-dot ${positions.some(p => p.account_id === id) ? '' : 'dim-dot'}`} />{accounts.find(a => a.id === id)?.name || id.slice(0, 8)}</span>)}</div></section></div></div><section className="panel strategy-log-panel"><div className="panel-heading"><h2><Activity size={16} /> 执行日志</h2><span className="dim">最新 50 条</span></div><div className="strategy-logs">{data.logs.length ? [...data.logs].sort((a, b) => dateValue(b.time) - dateValue(a.time)).slice(0, 50).map(log => <div className={`log-line ${log.level}`} key={log.id}><time>{dateText(log.time, true)}</time><span className="log-level">{log.level.toUpperCase()}</span><p>{log.message}</p></div>) : <div className="empty-state compact-empty"><Activity size={23} /><p>启动策略后，执行事件会显示在这里。</p></div>}</div></section></>}
      {page === 'bridge' && <>
        <div className="bridge-hero"><div className="bridge-hero-icon"><Link2 size={30} /></div><div><span className="page-eyebrow">BROWSER CONNECTION</span><h2>读取账户，切换模式，即可使用。</h2><p>账户从已登录的 Vest 页面自动发现。<br />只读与执行由插件中的一个模式开关控制。</p></div><span className={`outline-badge ${executionAccounts.length ? 'positive' : ''}`}><i className={`live-dot ${executionAccounts.length ? '' : 'inactive'}`} />{executionAccounts.length ? `${executionAccounts.length} 个账户可执行` : '插件只读模式'}</span></div>
        {ObservedAccountsPanel()}
        <div className="bridge-grid"><section className="panel bridge-setup"><div className="panel-heading"><h2>开始使用</h2><span className="outline-badge">Chrome / Edge</span></div>
          <div className="setup-step"><span className="step-number">1</span><div><h3>连接本地工作空间</h3><p>安装本地插件后，复制配对码并粘贴到插件。此配对只连接当前工作台，之后无需为每个账户单独配置。</p><div className="inline-buttons"><button className="button primary small pairing-copy-action" disabled={!!busy} onClick={() => void copyPairingCode()}><Copy size={13} />一键复制配对码</button><a className="button ghost small" href="/vest-browser-bridge.zip" download><Download size={14} />下载插件</a></div>{bridgeConfig ? <div className="pairing-details"><div><label>服务地址</label><code>{bridgeConfig.endpoint}</code><button className="icon-button" aria-label="复制服务地址" onClick={() => void copy(bridgeConfig.endpoint)}><Copy size={13} /></button></div><div><label>配对令牌</label><code title={bridgeConfig.token}>{bridgeConfig.token}</code><button className="icon-button" aria-label="复制配对令牌" onClick={() => void copy(bridgeConfig.token)}><Copy size={13} /></button></div><button className="text-button" onClick={() => setBridgeConfig(null)}><Eye size={13} />隐藏配对信息</button></div> : <button className="button ghost small" disabled={!!busy} onClick={async () => { setBusy('pairing'); try { setBridgeConfig(await request('/api/bridge/config')); } catch (caught) { toast(caught instanceof Error ? caught.message : '无法显示配对信息', true); } finally { setBusy(''); } }}><Link2 size={14} />显示配对信息</button>}</div></div>
          <div className="setup-step"><span className="step-number">2</span><div><h3>读取 Vest 账户</h3><p>在已登录的 Vest 标签页打开插件，点击「读取账户」。账户、净值和浮动盈亏会自动加入工作台；无需手工创建账户。读取完成后恢复原来查看的账户。</p><div className="inline-buttons"><a className="button ghost small" href="https://next.vestmarkets.com/trade/NQ-PERP" target="_blank" rel="noreferrer">打开 Vest <ExternalLink size={13} /></a><button className="text-button" onClick={() => document.getElementById('vest-page-accounts')?.scrollIntoView({ behavior: 'smooth', block: 'start' })}><Eye size={13} />查看账户</button></div></div></div>
          <div className="setup-step"><span className="step-number">3</span><div><h3>在插件切换「只读 / 执行」</h3><p>只读模式查看账户与行情；执行模式允许所选账户下单和运行策略。切回只读立即停止后续执行，尚未发送的任务会取消。已经提交到 Vest 的订单及原生止盈止损仍以平台状态为准。</p><div className="plugin-mode-preview"><span><Eye size={15} />只读 <small>查看与监控</small></span><ArrowRight size={16} /><span className="positive"><Play size={15} />执行 <small>下单与自动策略</small></span></div></div></div>
        </section><div className="bridge-side"><section className="panel bridge-principles"><span className="bridge-shield"><ShieldCheck size={23} /></span><h3>一个开关，清楚掌握权限。</h3><p>账户识别和页面准备自动完成。工作台只展示权限状态，不会自行开启插件执行模式。</p><div><Check size={14} />默认只读，断线或重启回到只读</div><div><Check size={14} />切换账户后自动核验新鲜读数</div><div><Check size={14} />成交结果未知时暂停，不重复发送</div><div><Check size={14} />模式切换不主动平仓</div></section><section className="panel plugin-session-card"><div className="panel-heading"><h2>当前插件状态</h2><span className={`status-pill ${executionAccounts.length ? 'positive' : 'muted'}`}>{executionAccounts.length ? '执行' : '只读'}</span></div><div className="plugin-session-content"><strong>{browserRows.length}<small>个已发现账户</small></strong><p>{executionAccounts.length ? `${executionAccounts.length} 个账户允许执行，可在工作台选择账户池。` : '在插件中切换执行模式后，符合条件的账户即可用于下单。'}</p><button className="text-button" onClick={() => setPage('dashboard')}>返回交易工作台<ArrowRight size={13} /></button></div></section></div></div>
      </>}
    </>}</main></div>
    {showAdd && mode === 'paper' && <div className="modal-backdrop" onClick={() => setShowAdd(false)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="add-account-title" onClick={event => event.stopPropagation()}><div className="modal-heading"><div><span className="page-eyebrow">NEW ACCOUNT</span><h2 id="add-account-title">添加模拟账户</h2></div><button className="icon-button" aria-label="关闭添加账户" onClick={() => setShowAdd(false)}><X size={20} /></button></div><form onSubmit={async event => { event.preventDefault(); const success = await perform('/api/accounts', { ...accountDraft, name: accountDraft.name.trim(), mode: 'paper' }, '账户已添加'); if (success) { setShowAdd(false); setAccountDraft({ name: '', initial_balance: 10000, profit_target: 800, max_loss: 500 }); } }}><Field label="账户名称"><input autoFocus required maxLength={40} placeholder="例如：Vest Alpha 01" value={accountDraft.name} onChange={event => setAccountDraft({ ...accountDraft, name: event.target.value })} /></Field><Field label="初始模拟资金" suffix="USDC"><input required type="number" min="1" step="any" value={accountDraft.initial_balance} onChange={event => setAccountDraft({ ...accountDraft, initial_balance: Number(event.target.value) })} /></Field><div className="two-columns"><Field label="账户盈利目标" suffix="USDC"><input required type="number" min="0.01" step="any" value={accountDraft.profit_target} onChange={event => setAccountDraft({ ...accountDraft, profit_target: Number(event.target.value) })} /></Field><Field label="账户最大亏损" suffix="USDC"><input required type="number" min="0.01" max={accountDraft.initial_balance} step="any" value={accountDraft.max_loss} onChange={event => setAccountDraft({ ...accountDraft, max_loss: Number(event.target.value) })} /></Field></div><div className="modal-note"><ShieldCheck size={15} />资金与订单均为本地模拟，不影响任何真实账户。</div><div className="modal-actions"><button className="button ghost" type="button" onClick={() => setShowAdd(false)}>取消</button><button className="button primary" type="submit" disabled={!!busy || !accountDraft.name.trim()}>{busy === '/api/accounts' ? <LoaderCircle className="spin" size={15} /> : <Plus size={15} />}创建账户</button></div></form></section></div>}
    {phaseDetail && <div className="modal-backdrop" onClick={() => setPhaseDetailId(null)}><section className="modal phase-modal" role="dialog" aria-modal="true" aria-labelledby="phase-title" onClick={event => event.stopPropagation()}><div className="modal-heading"><div><h2 id="phase-title">{phaseDetail.name} · 阶段明细</h2><small>当前阶段：{phaseDetail.phase || '待识别'}</small></div><button className="icon-button" aria-label="关闭阶段明细" onClick={() => setPhaseDetailId(null)}><X size={20} /></button></div><div className="table-scroll"><table><thead><tr><th>阶段</th><th className="numeric">已记录盈亏</th><th className="numeric">最大日亏损</th><th className="numeric">最大回撤</th><th className="numeric">阶段目标</th><th>当日开仓</th></tr></thead><tbody>{phases.map(phase => {
      const book = phaseDetail.phase_books?.[phase];
      const metric = (key: keyof CapitalMetrics) => { const m = book?.capital_metrics?.[key]; return m ? m.percent != null ? `${money(m.percent)}%` : `${money(m.current)} / ${money(m.limit)}` : '—'; };
      return <tr key={phase}><td><strong>{phase}</strong>{phase === phaseDetail.phase && <small className="cell-subtitle">当前阶段</small>}</td><td className="numeric">{signed(book?.history_realized_pnl)}{book && <small className="cell-subtitle">{book.history_trade_count ?? 0} 笔{book.settlement_pending ? ' · 旧阶段结算待补' : ''}</small>}</td><td className="numeric">{metric('daily_loss')}</td><td className="numeric">{metric('drawdown')}</td><td className="numeric">{metric('goal')}</td><td>{book ? book.daily_entry_used ? '已使用' : '未使用' : '未进入'}</td></tr>;
    })}</tbody></table></div><p className="phase-note">每个阶段独立统计，风控数值保留该阶段最后一次页面读数。盈亏仅含本工具已记录的平仓历史；未识别阶段的旧交易保留在历史中。每日额度按美东 20:00 重置，进入下一阶段时单独获得一单额度。</p></section></div>}
    {confirmAction && <div className="modal-backdrop" onClick={() => setConfirmAction(null)}><section className="modal confirm-modal" role="dialog" aria-modal="true" aria-labelledby="confirm-title" onClick={event => event.stopPropagation()}><div className="confirm-icon"><ShieldCheck size={25} /></div><h2 id="confirm-title">{confirmAction.title}</h2><p>{confirmAction.description}</p><div className="modal-actions"><button className="button ghost" onClick={() => setConfirmAction(null)}>取消</button><button className="button primary" onClick={() => { const action = confirmAction.run; setConfirmAction(null); action(); }}>确认执行<ArrowRight size={15} /></button></div></section></div>}
    <div className="toast-stack" aria-live="polite">{toasts.map(item => <div className={`toast ${item.error ? 'error' : ''}`} key={item.id}>{item.error ? <CircleHelp size={17} /> : <CheckCheck size={17} />}<span>{item.message}</span><button aria-label="关闭提示" onClick={() => setToasts(current => current.filter(t => t.id !== item.id))}><X size={14} /></button></div>)}</div>
  </div>;
}
